<template><div class="form-list"><b>{{ team }}</b><div v-if="rows.length" class="form-items"><span v-for="r in rows" :key="r.id" :class="resultClass(r)">{{ resultLetter(r) }}</span></div><small v-else class="muted">No recent results</small></div></template>
<script setup lang="ts">defineProps<{team:string;rows:any[]}>();function resultLetter(r:any){const text=String(r.result||'').toLowerCase();if(text.includes('draw'))return'D';if(text.includes('won')||text.includes('win'))return'W';if(text.includes('lost')||text.includes('lose'))return'L';return'—'}function resultClass(r:any){return resultLetter(r).toLowerCase()}</script>
